import{BRACKISH_ROLES as ROWS}from'./npc-registration.mjs';
const moduleURL=import.meta.url,hash=async b=>[...new Uint8Array(await crypto.subtle.digest('SHA-256',b))].map(x=>x.toString(16).padStart(2,'0')).join('');
export async function loadBrackishNPCs({fetcher=fetch,decode=async b=>createImageBitmap(new Blob([b])),signal}={}){let disposed=false;const images=[];const check=()=>{if(disposed||signal?.aborted)throw Error('BRACKISH_NPC_CANCELLED')};const dispose=()=>{if(disposed)return;disposed=true;let first;for(const image of images.splice(0))try{image.close?.()}catch(e){first??=e}if(first)throw first};try{for(const r of ROWS){check();const response=await fetcher(new URL('../../'+r.atlas.src,moduleURL),{signal});if(!response.ok)throw Error('BRACKISH_NPC_LOAD');const b=new Uint8Array(await response.arrayBuffer());check();if(await hash(b)!==r.atlas.sha256)throw Error('BRACKISH_NPC_ATLAS_PIN');check();const image=await decode(b);images.push(image);check();if(image.width!==r.atlas.width||image.height!==r.atlas.height)throw Error('BRACKISH_NPC_DIMENSIONS')}return Object.freeze({drawLayers(ctx,origin){check();return ROWS.map((r,i)=>({y:r.npcFoot[1],draw(){check();const[x,y,w,h]=r.atlasFrame.rect,dw=w*80/h;ctx.drawImage(images[i],x,y,w,h,r.npcFoot[0]-origin[0]-dw/2,r.npcFoot[1]-origin[1]-80,dw,80)}}))},dispose})}catch(e){try{dispose()}catch{}throw e}}
